5	/**
6	 * Tokens are valid for 20 minutes. Cached at module scope and reused across
7	 * lambda invocations. Refreshed after 15 minutes.
8	 */
9	let marketingCloudToken = '';
10	let marketingCloudTokenExpiration = new Date();
11	
12	type MarketingCloudConfig = {
13	  clientId: string | undefined;
14	  clientSecret: string | undefined;
15	  subdomain: string | undefined;
16	  templateId: string | undefined;
17	  magicLink: string;
18	};
19	
20	function generateUniqueId(): string {
21	  return crypto.randomBytes(16).toString('hex');
22	}
23	
24	/**
25	 * Sends an email to a specified contact using the Marketing Cloud API. The template email must have a
26	 * `%%magic-link%%` personalization string inserted.
27	 * https://help.salesforce.com/s/articleView?id=mktg.mc_es_personalization_strings.htm&type=5
28	 */
29	async function sendMarketingCloudEmail(emailId: string, marketingCloudConfig: MarketingCloudConfig): Promise<unknown> {
30	  const { clientId, clientSecret, subdomain } = marketingCloudConfig;
31	  if (!clientId || !clientSecret || !subdomain) {
32	    throw new Error('Marketing Cloud credentials are missing: clientId, clientSecret, and subdomain are required.');
33	  }
34	
35	  // Refresh token if expired
36	  if (new Date() > marketingCloudTokenExpiration) {
37	    const tokenUrl = `https://${subdomain}.auth.marketingcloudapis.com/v2/token`;
38	    const tokenResponse = await fetch(tokenUrl, {
39	      method: 'POST',
40	      headers: { 'Content-Type': 'application/json' },
41	      body: JSON.stringify({
42	        grant_type: 'client_credentials',
43	        client_id: clientId,
44	        client_secret: clientSecret,
45	      }),
46	    });
47	
48	    if (!tokenResponse.ok)
49	      throw new Error(
50	        'Failed to fetch Marketing Cloud access token. Check your Marketing Cloud credentials and try again.',
51	      );
52	
53	    const { access_token } = (await tokenResponse.json()) as { access_token: string };
54	    marketingCloudToken = access_token;
55	    // Set expiration to 15 mins
56	    marketingCloudTokenExpiration = new Date(Date.now() + 15 * 60 * 1000);
57	  }
58	
59	  // Send the email
60	  const emailUrl = `https://${subdomain}.rest.marketingcloudapis.com/messaging/v1/email/messages/${generateUniqueId()}`;
61	  const emailResponse = await fetch(emailUrl, {
62	    method: 'POST',
63	    headers: {
64	      Authorization: `Bearer ${marketingCloudToken}`,
65	      'Content-Type': 'application/json',
66	    },
67	    body: JSON.stringify({
68	      definitionKey: marketingCloudConfig.templateId,
69	      recipient: {
70	        contactKey: emailId,
71	        to: emailId,
72	        attributes: { 'magic-link': marketingCloudConfig.magicLink },
73	      },
74	    }),
75	  });
76	
77	  if (!emailResponse.ok) throw new Error('Failed to send email to Marketing Cloud');
78	
79	  return emailResponse.json();
80	}
