46	/**
47	 * SFCC-681 as-is baseline evidence (see .docs/temp/tsd-architecture.md §12.1 and
48	 * overrides/app/ssr/connectionPools.ts). These use the real handler functions, not
49	 * stand-ins, to demonstrate today's shared-process failure isolation gap and give
50	 * the TSD's Options Analysis / Risks sections real, reproducible evidence instead
51	 * of an assertion. Every fetch here is mocked; nothing calls a real network endpoint.
52	 */
53	describe('SSR shared-process blast radius (SFCC-681 as-is baseline)', () => {
54	  beforeEach(() => {
55	    vi.stubEnv('MARKETING_CLOUD_CLIENT_ID', 'test-client-id');
56	    vi.stubEnv('MARKETING_CLOUD_CLIENT_SECRET', 'test-client-secret');
57	    vi.stubEnv('MARKETING_CLOUD_SUBDOMAIN', 'test-subdomain');
58	
59	    vi.mocked(getConfig).mockReturnValue({
60	      app: {
61	        sfPayments: { metadataUrl: PAYMENTS_URL },
62	        login: { resetPassword: { landingPath: '/reset-password' }, passwordless: {} },
63	      },
64	    } as ReturnType<typeof getConfig>);
65	
66	    vi.stubGlobal(
67	      'fetch',
68	      vi.fn((input: string | URL) => {
69	        const href = String(input);
70	        if (href.includes('payments.example.demandware.net')) {
71	          return Promise.resolve({ ok: true, json: () => Promise.resolve({ paymentMethodTypes: {} }) } as Response);
72	        }
73	        if (href.includes('auth.marketingcloudapis.com')) {
74	          return Promise.resolve({ ok: true, json: () => Promise.resolve({ access_token: 'fake-token' }) } as Response);
75	        }
76	        if (href.includes('rest.marketingcloudapis.com')) {
77	          // Simulates Marketing Cloud's send-email endpoint being down — the
78	          // token exchange above succeeds, only the send call fails.
79	          return Promise.resolve({ ok: false, status: 503 } as Response);
80	        }
81	        return Promise.reject(new Error(`Unexpected fetch in test: ${href}`));
82	      }),
83	    );
84	  });
