86	  test('Test 1 — a failing integration silently discards an unrelated, already-succeeded one', async () => {
87	    const paymentsRes = createMockRes();
88	    const magicLinkRes = createMockRes();
89	
90	    const paymentsCall = paymentMetadataHandler({}, paymentsRes);
91	    const magicLinkCall = sendMagicLinkEmail(createMockReq(), magicLinkRes, '/reset-password', 'reset-template');
92	
93	    // Ground truth, checked independently of one another: payment metadata
94	    // genuinely succeeds; the magic-link send genuinely rejects uncaught —
95	    // sendMagicLinkEmail has no try/catch around its Marketing Cloud call,
96	    // unlike paymentMetadataHandler and jwksCaching, which both catch their
97	    // own fetch failures and turn them into HTTP error responses.
98	    const [paymentsOutcome, magicLinkOutcome] = await Promise.allSettled([paymentsCall, magicLinkCall]);
99	    expect(paymentsOutcome.status).toBe('fulfilled');
100	    expect(magicLinkOutcome.status).toBe('rejected');
101	    expect(paymentsRes.body).toEqual(expect.objectContaining({ paymentMethodTypes: {} }));
102	
103	    // What a normal caller aggregating "I need both of these" via Promise.all
104	    // actually experiences today: total failure. The successful payment data
105	    // was sitting right there, computed, one line above — Promise.all discards
106	    // it the moment the sibling call rejects, with no way for the caller to
107	    // recover it.
108	    const paymentsRes2 = createMockRes();
109	    const magicLinkRes2 = createMockRes();
110	    await expect(
111	      Promise.all([
112	        paymentMetadataHandler({}, paymentsRes2),
113	        sendMagicLinkEmail(createMockReq(), magicLinkRes2, '/reset-password', 'reset-template'),
114	      ]),
115	    ).rejects.toThrow(/Marketing Cloud/i);
116	  });
