142	  test('Test 2 — a synchronous, CPU-bound task blocks every other concurrent request on the same process', async () => {
143	    // No mocking here — this is a genuine property of Node's single-threaded
144	    // event loop, not something specific to any one integration's code, and not
145	    // something undici connection pools can fix (pools govern network sockets,
146	    // not who holds the JS thread).
147	    let fastResolvedAt = 0;
148	    const start = Date.now();
149	
150	    const fastRequest = Promise.resolve().then(() => {
151	      fastResolvedAt = Date.now();
152	    });
153	
154	    const BLOCK_MS = 200;
155	    const blockUntil = Date.now() + BLOCK_MS;
156	    while (Date.now() < blockUntil) {
157	      // Deliberately busy-wait — stands in for a heavy synchronous operation
158	      // (a large JSON.parse, a slow regex) inside some integration's handler.
159	    }
160	
161	    await fastRequest;
162	    const fastRequestDelay = fastResolvedAt - start;
163	
164	    // The "fast" request should resolve near-instantly. Instead it's held
165	    // hostage behind the blocking work for the full BLOCK_MS, because they
166	    // share one event loop — there is no infrastructure fix for this; it's an
167	    // accepted trade-off of the single-app model, mitigated only by a coding
168	    // rule (never block synchronously in an integration handler), not wiring.
169	    expect(fastRequestDelay).toBeGreaterThanOrEqual(BLOCK_MS - 5);
170	  });
